components.css:
.ds-btn-primary { background: var(--shell); color: var(--paper); padding: 0.4rem 0.85rem; min-height: 2.75rem; border: 1px solid var(--shell); border-radius: 2px; font-family: var(--text); font-weight: 700; font-size: 1.0625rem; cursor: pointer; }
.ds-btn-primary:hover { background: var(--shell); color: var(--paper); }
.ds-btn-primary:focus-visible { outline: 2px solid var(--ink); outline-offset: 3px; }

.ds-btn-toggle { min-height: 2.75rem; padding: 0.35rem 0.8rem; background: transparent; color: var(--ink); border: 1px solid var(--ink); border-radius: 2px; font-family: var(--text); font-weight: 700; font-size: 1.0625rem; cursor: pointer; }
.ds-btn-toggle:hover { background: transparent; }
.ds-btn-toggle:focus-visible { outline: 2px solid var(--ink); outline-offset: 3px; }

.ds-btn-toggle-pressed { min-height: 2.75rem; padding: 0.35rem 0.8rem; background: var(--shell); color: var(--paper); border: 1px solid var(--shell); border-radius: 2px; font-family: var(--text); font-weight: 700; font-size: 1.0625rem; cursor: pointer; }
.ds-btn-toggle-pressed:hover { background: var(--shell); color: var(--paper); }
.ds-btn-toggle-pressed:focus-visible { outline: 2px solid var(--ink); outline-offset: 3px; }

.ds-marker { position: relative; display: flex; flex-direction: column; align-items: flex-start; gap: 0.05rem; width: max-content; min-width: 5.8rem; min-height: 5.4rem; padding: 0.85rem 0.75rem 0.55rem; background: var(--plate); color: var(--ink); border: 2px solid var(--ink); border-radius: 2px; text-align: left; font-family: var(--text); cursor: pointer; }
.ds-marker::before { content: ""; position: absolute; top: 0; left: 0; right: 0; height: 7px; background: var(--mark); }
.ds-marker:hover { background: var(--plate); }
.ds-marker:focus-visible { outline: 2px solid var(--ink); outline-offset: 3px; }
.ds-marker-code { margin-top: 0.2rem; font-family: var(--display); font-weight: 800; font-size: 1.7rem; line-height: 0.9; letter-spacing: -0.03em; }
.ds-marker-name { font-size: 0.78rem; font-weight: 700; }
.ds-marker-time { font-family: var(--display); font-weight: 700; font-size: 1.15rem; letter-spacing: -0.02em; font-variant-numeric: tabular-nums; }

.ds-marker { position: relative; display: flex; flex-direction: column; align-items: flex-start; gap: 0.05rem; width: max-content; min-width: 5.8rem; min-height: 5.4rem; padding: 0.85rem 0.75rem 0.55rem; background: var(--plate); color: var(--ink); border: 2px solid var(--ink); border-radius: 2px; text-align: left; font-family: var(--text); cursor: pointer; }
.ds-marker::before { content: ""; position: absolute; top: 0; left: 0; right: 0; height: 7px; background: var(--mark); }
.ds-marker.is-selected, .ds-marker:focus-visible { outline: 2px solid var(--ink); outline-offset: 3px; }
.ds-marker:hover { background: var(--plate); }
.ds-marker-code { margin-top: 0.2rem; font-family: var(--display); font-weight: 800; font-size: 1.7rem; line-height: 0.9; letter-spacing: -0.03em; }
.ds-marker-name { font-size: 0.78rem; font-weight: 700; }
.ds-marker-time { font-family: var(--display); font-weight: 700; font-size: 1.15rem; letter-spacing: -0.02em; font-variant-numeric: tabular-nums; }

.ds-field { display: grid; gap: 0.28rem; font-family: var(--text); font-size: 0.8125rem; font-weight: 700; color: var(--ink); }
.ds-input { width: 16rem; min-height: 2.75rem; padding: 0.4rem 0.7rem; background: var(--plate); color: var(--ink); border: 1px solid var(--ink); border-radius: 2px; font-family: var(--text); font-size: 1.0625rem; font-weight: 400; caret-color: var(--ink); }
.ds-input::placeholder { color: var(--ink-soft); opacity: 1; }
.ds-input:hover { border-color: var(--ink); }
.ds-input:focus-visible { outline: 2px solid var(--ink); outline-offset: 3px; }

.ds-shell { display: flex; align-items: center; justify-content: space-between; gap: 1rem; min-height: 4rem; padding: 0.4rem 1rem; background: var(--shell); color: var(--paper); box-shadow: var(--shadow); font-family: var(--text); }
.ds-brand { font-family: var(--display); font-weight: 800; font-size: 1.85rem; letter-spacing: -0.03em; line-height: 1; color: var(--paper); text-decoration: none; }
.ds-nav { display: flex; gap: 0.25rem 1rem; }
.ds-nav a { color: var(--paper); font-weight: 600; text-decoration: none; padding: 0.35rem 0; font-size: 1.0625rem; }
.ds-nav a:hover { color: var(--paper); }
.ds-nav a[aria-current="true"] { text-decoration: underline; text-decoration-thickness: 3px; text-decoration-color: var(--mark); text-underline-offset: 0.35em; }
.ds-shell a:focus-visible { outline: 2px solid var(--mark); outline-offset: 3px; }

.ds-sheet { width: min(100%, 36rem); }
.ds-race { display: grid; grid-template-columns: minmax(0, 1fr) auto auto; column-gap: 0.75rem; row-gap: 0.1rem; align-items: center; width: 100%; padding: 0.75rem 0.15rem; background: transparent; color: var(--ink); border: 0; border-bottom: 1px solid var(--line); text-align: left; font-family: var(--text); font-size: 1.0625rem; cursor: pointer; }
.ds-race:hover { background: rgba(247, 248, 244, 0.7); }
.ds-race.is-open { border-bottom-color: transparent; background: var(--plate); }
.ds-race.is-open:hover { background: var(--plate); }
.ds-race:focus-visible { outline: 2px solid var(--ink); outline-offset: 3px; }
.ds-race-date { grid-column: 1; grid-row: 1; color: var(--ink-soft); font-size: 0.875rem; font-weight: 600; font-variant-numeric: tabular-nums; }
.ds-race-time { grid-column: 2; grid-row: 1; font-family: var(--display); font-weight: 700; font-size: 1.45rem; letter-spacing: -0.02em; font-variant-numeric: tabular-nums; text-align: right; }
.ds-race-time.is-missing { font-family: var(--text); font-size: 0.95rem; font-weight: 700; color: var(--missing); letter-spacing: 0; }
.ds-race-chev { grid-column: 3; grid-row: 1 / span 3; width: 1rem; height: 1rem; align-self: center; }
.ds-race.is-open .ds-race-chev { transform: rotate(180deg); }
.ds-race-name { grid-column: 1 / span 2; grid-row: 2; font-weight: 700; }
.ds-race-dist { grid-column: 1 / span 2; grid-row: 3; font-size: 0.8125rem; font-weight: 700; color: var(--ink-soft); }
.ds-chip { display: inline-block; margin-left: 0.4rem; padding: 0.05rem 0.35rem; border: 1px solid var(--line); font-family: var(--text); font-size: 0.75rem; font-weight: 700; color: var(--ink-soft); }

.ds-splits { font-family: var(--text); color: var(--ink); max-width: 36rem; }
.ds-split-bar { display: flex; height: 0.8rem; gap: 3px; }
.ds-split-bar i { display: block; min-width: 0.35rem; background: var(--segment, var(--ink)); }
.ds-split-key { display: grid; grid-template-columns: repeat(3, minmax(7rem, 1fr)); gap: 0.75rem; margin-top: 0.55rem; }
.ds-split-key p { margin: 0; }
.ds-split-key span { display: block; font-size: 0.78rem; font-weight: 700; }
.ds-swatch { display: inline-block; width: 0.7rem; height: 0.7rem; margin-right: 0.3rem; background: var(--segment, var(--ink)); vertical-align: -0.05rem; }
.ds-split-key strong { font-family: var(--display); font-weight: 700; font-size: 1.45rem; letter-spacing: -0.02em; font-variant-numeric: tabular-nums; }
